                payment = {
                    "request_id": request_id,
                    "amount_cents": amount_cents,
                    "result": "applied",
                    "duplicate": False,
                }
            conn.execute("COMMIT")
    finally:
        conn.close()
    order = get(tenant, order_id)
    if payment is not None:
        order["payment"] = payment
    return order

